import json
for i in (5,6):
    m=json.load(open('data/%d/metadata.json'%i))
    print('=== run',i, m.get('function'), 'slow_delay',m.get('slow_delay'),'fast_delay',m.get('fast_delay'),'delay',m.get('delay'))
    ins=m.get('instruments')
    if i==5:
        import pprint
        for k,v in (ins or {}).items():
            if k.startswith('sr'):
                print(k, {kk:vv for kk,vv in v.items() if kk in ('time_constant','filter_slope','sensitivity','frequency','amplitude','phase','reserve')})
            if '2400' in k:
                print(k, list(v.keys())[:20])
"

